            why: string;
            /** @enum {string} */
            category: "meals" | "home" | "gear" | "care" | "learning" | "rest" | "together";
            /** @description Written for the parent who is not pregnant. Either parent can take any mission. */
            forPartner: boolean;
            /** @enum {string} */
            state: "open" | "taken" | "done";
